#include <Stepper.h>

// Количество шагов для полного оборота внутренностей мотора 28BYJ-48 с учетом редуктора
const int stepsPerRevolution = 2048; 

// Инициализируем библиотеку. 
// Важно: порядок пинов изменен на 8, 10, 9, 11 — это особенность мотора 28BYJ-48
Stepper myStepper(stepsPerRevolution, 8, 10, 9, 11);

void setup() {
  // Устанавливаем скорость вращения (обороты в минуту).
  // Для этого мотора оптимальная скорость от 5 до 15. Если поставить слишком много, он заклинит.
  myStepper.setSpeed(12); 
}

void loop() {
  // Команда сделать 20 шагов в одну сторону.
  // Так как функция loop() выполняется бесконечно, мотор будет крутиться непрерывно.
  myStepper.step(20); 
}
